  AND to_user_id = #{toUserId}
  AND rel_status = 1

mapper.insert:
INSERT INTO follower (
    id, to_user_id, from_user_id, rel_status, created_at, updated_at
) VALUES (
    #{id}, #{toUserId}, #{fromUserId}, 1, #{createdAt}, #{updatedAt}
)
ON DUPLICATE KEY UPDATE
    rel_status = 1,
    created_at = VALUES(created_at),
    updated_at = VALUES(updated_at)

mapper.update:
UPDATE follower
SET rel_status = 0,
    updated_at = #{updatedAt}
WHERE to_user_id = #{toUserId}
  AND from_user_id = #{fromUserId}
  AND rel_status = 1

mapper.select:
SELECT id, from_user_id, to_user_id, rel_status, created_at, updated_at
FROM following
WHERE from_user_id = #{fromUserId}
  AND to_user_id = #{toUserId}

SELECT id, from_user_id, to_user_id, rel_status, created_at, updated_at
FROM follower
WHERE to_user_id = #{toUserId}
  AND from_user_id = #{fromUserId}

SELECT EXISTS(
    SELECT 1
    FROM following
    WHERE from_user_id = #{fromUserId}
      AND to_user_id = #{toUserId}
      AND rel_status = 1
)

SELECT to_user_id AS userId, created_at AS createdAt
FROM following
WHERE from_user_id = #{fromUserId}
  AND rel_status = 1
ORDER BY created_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT from_user_id AS userId, created_at AS createdAt
FROM follower
WHERE to_user_id = #{toUserId}
  AND rel_status = 1
ORDER BY created_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT to_user_id AS userId, created_at AS createdAt
FROM following
WHERE from_user_id = #{fromUserId}
  AND rel_status = 1
  AND created_at < #{cursor}
ORDER BY created_at DESC, id DESC
LIMIT #{limit}

SELECT from_user_id AS userId, created_at AS createdAt
FROM follower
WHERE to_user_id = #{toUserId}
  AND rel_status = 1
  AND created_at < #{cursor}
ORDER BY created_at DESC, id DESC
LIMIT #{limit}
